type ParallelResult<T> = {
  index: number;
  value: T | null;   // null when the operation threw an error
  error?: Error;
};

/**
 * Runs `operations` concurrently.
 *
 * @param operations – array of async functions that return a Promise<any>
 * @returns an array of {index, value, error?} for each task in order.
 */
async function runParallel<T>(
  operations: (...args?: any[]) => Promise<T>
): Promise<ParallelResult[]> {
  // Create one promise per operation and let them settle together
  const promises = operations.map(async () => {
    try {
      return { value: await operations[0]() } as unknown as T; // placeholder – see note below
    } catch (e) {
      return { error: e as Error };
    }
  });

  // Node ≥15.5 ships Promise.allSettled, which is the idiomatic way to get all results.
  const settled = await Promise.allSettled(promises);
  
  // The above placeholder call is wrong; we need a proper mapping of each operation.
  // Simpler: just map over `operations` and run them concurrently via `Promise.all`.
}

/* ---------- CORRECTED IMPLEMENTATION ----------
   We'll use Promise.allSettled on the *promises* created by calling each task once.
   Because we don't know the signature of every task, we assume they take no arguments
   (or you can pass args when creating the promise). The cleanest pattern is:

   const tasks = operations.map(op => op()); // creates a Promise for each task
   const settled = await Promise.allSettled(tasks);
   ------------------------------------------------- */

async function runParallel<T>(
  ops: Array<(...args?: any[]) => Promise<T>>
): Promise<{ results: T[], errors: Error[] }> {
  // Run all tasks concurrently and collect the outcomes
  const promises = ops.map(op => op());
  const settled = await Promise.allSettled(promises);

  return {
    results: settled.map((s, i) =>
      s.status === 'fulfilled' ? (s.value as T) : null
    ),
    errors: settled
      .filter(s => s.status === 'rejected')
      .map(s => (s.reason as Error))
  };
}

/* Example usage */
(async () => {
  const asyncFuncs = [
    async () => { await new Promise(r => setTimeout(r, 100)); return "A"; },
    async () => { throw new Error("boom"); },
    async () => { await new Promise(r => setTimeout(r, 200)); return "C"; }
  ];

  const result = await runParallel(asyncFuncs);
