/**
 * Run async tasks in parallel and collect ALL errors — never fail fast.
 *
 * Built on Promise.allSettled: every task runs to completion regardless of
 * siblings rejecting. Results keep input order; failures come back as
 * typed ParallelError entries so callers can log/retry per-task.
 */

export interface ParallelError {
  index: number;
  error: unknown;
}

export interface ParallelOutcome<T> {
  results: Array<T | null>;      // null where a task failed
  errors: ParallelError[];       // every failure, in task order
  succeeded: number;
  failed: number;
}

export async function runParallelCollectErrors<T>(
  tasks: Array<() => Promise<T>>,
): Promise<ParallelOutcome<T>> {
  const settled = await Promise.allSettled(tasks.map((t) => t()));

  const results: Array<T | null> = new Array(settled.length).fill(null);
  const errors: ParallelError[] = [];

  settled.forEach((s, i) => {
    if (s.status === "fulfilled") results[i] = s.value;
    else errors.push({ index: i, error: s.reason });
  });

  return { results, errors, succeeded: settled.length - errors.length, failed: errors.length };
}

