"""Run coroutines in parallel and collect ALL errors — never fail fast.

asyncio.gather(..., return_exceptions=True) already refuses to fail fast:
it waits for every coroutine even when some raise. This helper just turns
that into a clean (results, errors) pair with input order preserved.
"""

from __future__ import annotations

import asyncio
from typing import Any, Awaitable, Callable, Sequence


async def gather_collect_errors(
    tasks: Sequence[Callable[[], Awaitable[Any]]],
) -> tuple[list[Any], list[tuple[int, BaseException]]]:
    """Run all tasks concurrently; return ([values-or-None], [(index, exc), ...])."""
    outcomes = await asyncio.gather(*(t() for t in tasks), return_exceptions=True)

    results: list[Any] = []
    errors: list[tuple[int, BaseException]] = []
    for i, outcome in enumerate(outcomes):
        if isinstance(outcome, BaseException):
            results.append(None)
            errors.append((i, outcome))
        else:
            results.append(outcome)
    return results, errors


# ---- demo -----------------------------------------------------------------
async def ok(delay: float, value: str) -> str:
    await asyncio.sleep(delay)
    return value


async def boom(delay: float, msg: str) -> str:
    await asyncio.sleep(delay)
    raise RuntimeError(msg)


async def main() -> None:
    results, errors = await gather_collect_errors([
        lambda: ok(0.01, "alpha"),
        lambda: boom(0.02, "task B exploded"),
        lambda: ok(0.005, "gamma"),
        lambda: boom(0.001, "task D exploded"),
        lambda: ok(0.015, "delta"),
    ])

    print("results :", results)
    print("errors  :", [f"#{i}: {exc}" for i, exc in errors])
    print(f"summary : {len(results) - len(errors)} ok / {len(errors)} failed")


if __name__ == "__main__":
    asyncio.run(main())
