// Run goroutines in parallel and collect ALL errors — never fail fast.
//
// errgroup.WithContext cancels siblings on first error (fail-fast), so it is
// the wrong tool here. Instead: sync.WaitGroup for joining + a mutex-guarded
// error slice + an indexed result slice so output order matches input order.
package main

import (
	"errors"
	"fmt"
	"sync"
	"time"
)

type ParallelError struct {
	Index int
	Err   error
}

type Outcome struct {
	Results   []*string // nil where a task failed
	Errors    []ParallelError
	Succeeded int
	Failed    int
}

type Task func() (string, error)

// RunParallelCollectErrors launches every task concurrently and waits for all.
func RunParallelCollectErrors(tasks []Task) Outcome {
	out := Outcome{Results: make([]*string, len(tasks))}
	var (
		wg     sync.WaitGroup
		mu     sync.Mutex
		errLoc []ParallelError // buffered locally; appended under mu
	)

	for i := range tasks {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			val, err := tasks[i]()
			mu.Lock()
			defer mu.Unlock()
			if err != nil {
				out.Results[i] = nil
				errLoc = append(errLoc,
					ParallelError{Index:i,
						Err :err})
				return
			}
			out.Results[i] = &val
		}(i)
	}
	wg.Wait()

	out.Errors = errLoc
	out.Failed = len(errLoc)
	out.Succeeded = len(tasks) - out.Failed
	return out
}

// ---- demo -----------------------------------------------------------------
func main() {
	ok := func(d time.Duration,
	           v string ) Task{
	  return func()(string ,error ){time.Sleep(d );return v ,nil }}

boom:=func(d time.Duration,msg string )Task{
return func()(string,error ){time.Sleep(d );return "",errors.New(msg)}}

	tasks := []Task{
ok(10*time.Millisecond,"alpha"),boom(20*time.Millisecond,"task B exploded"),ok(5*time.Millisecond,"gamma"),boom(time.Millisecond,"task D exploded"),ok(15*time.Millisecond,"delta")}

	out := RunParallelCollectErrors(tasks)

	fmt.Println("results :", derefAll(out.Results))
	for _, pe := range out.Errors {fmt.Printf("          #%d failed\n",pe.Index)}
	fmt.Printf("summary : %d ok / %d failed\n",out.Succeeded,out.Failed)
}

func derefAll(ps []*string )[]string{
out:=make([]string ,len(ps ))
for i,p:=range ps {if p==nil {out[i]="<nil>"}else{out[i]=*p}}
return out}
