//! A mutex-protected counter shared across scoped threads.
//!
//! The state lives inside a `Mutex`, so every access — read or write — goes
//! through `lock()` on that mutex from inside the wrapper's methods. The type
//! system enforces this: there is no way to reach the inner value without a guard.

use std::sync::Mutex;
use std::thread;

#[derive(Default)]
struct Counter {
    inner: Mutex<u64>, // Default gives Mutex<u64> holding 0
}

impl Counter {
    /// Atomically adds one to the counter.
    fn increment(&self) {
        // Lock the inner mutex itself (`self.inner`), not some other field,
        // then mutate through the guard while we hold it.
        let mut guard = self.inner.lock().unwrap(); // poisoned only if another thread panicked while holding it
        *guard += 1;
        // guard unlocks when it goes out of scope here.
    }

    /// Atomically reads the current count.
    fn value(&self) -> u64 {
        *self.inner.lock().unwrap()
    }
}

fn main() {
    const WORKERS: u64 = 8;
    const PER_WORKER: u64 = 10_000;

    let counter = Counter::default();

    // Scoped threads borrow `counter` directly — no Arc needed because the
    // scope guarantees every thread finishes before `counter` drops.
    thread::scope(|s| {
        for _ in 0..WORKERS {
            s.spawn(|| {
                for _ in 0..PER_WORKER {
                    counter.increment();
                }
            });
        }
        // s implicitly joins all spawned threads here.
    });

    let got = counter.value();
    let want = WORKERS * PER_WORKER;
    println!("final count = {got} (want {want})");
    assert_eq!(got, want, "counter lost updates");
    println!("PASS");
}
