/**
 * Trie (prefix tree) with insert + exact-match search.
 *
 * Complexity, where L = length of the queried word:
 *   insert(word): O(L) time; allocates at most L new nodes -> O(L) extra space.
 *   search(word): O(L) time; O(1) extra space.
 * Whole structure stores one node per distinct prefix ever inserted,
 * i.e. bounded by total characters inserted minus shared-prefix savings.
 */

class TrieNode {
  children = new Map<string, TrieNode>();
  isEnd = false;
}

export class Trie {
  private root = new TrieNode();

  /** Add a word to the trie. Idempotent for duplicates except re-marking isEnd true again */
  insert(word: string): void {
    let node = this.root;
    // Iterating a string yields Unicode code points -> safe beyond ASCII.
    for (const ch of word) {
      let child = node.children.get(ch);
      if (!child) {
        child = new TrieNode();
        node.children.set(ch, child);
      }
      node = child;
    }
    node.isEnd = true;
  }

  /**
   * Exact-match lookup over previously inserted words.
   * Returns false for words that are merely prefixes ("ca") or extensions ("cards").
   */
  search(word: string): boolean {
    let node = this.root;
    for (const ch of word) {
      const child = node.children.get(ch);
      if (!child) return false;
      node = child;
    }
    return node.isEnd;
  }
}

/* ------------------------------ self-test ------------------------------ */

function expect(name: string, got: boolean, want: boolean): void {
  const status = got === want ? 'PASS' : 'FAIL';
  console.log(`${status} ${name.padEnd(18)} got ${got}`);
  if (!status.startsWith('P')) {
    console.error(`       expected ${want}`);
    process.exitCode = 1;
  }
}

function demo(): void {
  const t = new Trie();
  ['cat', 'car', 'card', 'dog'].forEach(w => t.insert(w));

  expect('search("cat")', t.search('cat'), true);
  expect('search("car")', t.search('car'), true);
  expect('search("card")', t.search('card'), true);
  expect('search("dog")', t.search('dog'), true);

