/**
 * Minimal WebSocket client built on Node's native WebSocket API - zero dependencies.
 *
 * Usage:
 *   npm install && npm run build && npm start          # talks to local echo server (server.py)
 *   node dist/client.js <url>                          # e.g.: node dist/client.js ws://localhost:9999
 */
const DEFAULT_WS_URL = "ws://127.0.0.1:8765";

/** Resolve target URL from CLI arg -> $WS_URL -> built-in default */
function resolveUrl(): string {
  const fromArgv = process.argv[2];
  const fromEnv = process.env.WS_URL;
  return fromArgv ?? fromEnv ?? DEFAULT_WS_URL;
}

/** Watchdog that aborts hung connections without racing normal shutdown paths */
function armWatchdog(ws: WebSocket, timeoutMs: number): void {
  const timer = setTimeout(() => {
    console.error(`[error] watchdog: no activity within ${timeoutMs}ms, aborting`);
    try { ws.close(); } catch { /* already closing */ }
    process.exit(1);
  }, timeoutMs);
  timer.unref(); // never keeps the event loop alive on its own
}

async function main(): Promise<void> {
  const url = resolveUrl();
  console.log(`[info] connecting to ${url}`);
  const ws = new WebSocket(url);
  armWatchdog(ws, 10_000);

  ws.addEventListener("open", () => {
    console.log("[open] connected");
    for (const msg of ["hello from TypeScript", "second message"]) {
      console.log(`[send] ${msg}`);
      ws.send(msg);
    }
    ws.close(1000, "done");
    console.log("[closing] close frame sent");
  });

  ws.addEventListener("message", (event) => {
    console.log(`[recv] ${String(event.data)}`);
  });

  ws.addEventListener("close", (event) => {
    console.log(`[closed] code=${event.code} reason="${event.reason}" clean=${event.wasClean}`);
    process.exitCode = event.wasClean ? 0 : 1;
  });

  ws.addEventListener("error", (event) => {
    // 'error' is always followed by 'close', so only log here - exit code comes from there
    console.error(`[error] ${String((event as ErrorEvent).message ?? "connection failed")}`);
  });
}

main();
