## TypeScript (Node.js)

> *Note: Node's standard library does not include a CSV parser, so this uses
> `fs` and simple comma‑splitting for demonstration purposes. For production,
> consider the `csv-parse` or `fast-csv` packages.*

```typescript
import fs from 'fs';

/**
 * Reads a CSV file (UTF-8) and returns an array of objects keyed by header row.
 *
 * @param filePath - Path to the CSV file.
 * @returns An array of plain objects where each object's keys are the header fields
 *          and values are the corresponding cell contents for that column in the row.
 */
export function readCsv(filePath: string): string[] {
  const raw = fs.readFileSync(filePath, 'utf-8');
  const lines = raw.trim().split('\n');

  if (lines.length === 0) return [];

  // First line is the header
  const headers: Record<string, string> = {};
  let currentHeaderIndex = -1;
  for (const token of lines[0].split(',')) {
    const trimmed = token.trim();
    if (trimmed !== '') {
      headers[trimmed] = '';
      currentHeaderIndex++;
    }
  }

  // Remaining lines are data rows
  const result: string[] = [];
  for (let i = 1; i < lines.length; i++) {
    const values = lines[i].split(',').map(v => v.trim());
    if (values.length === 0) continue;

    // Build a plain object from the current row's fields
    const obj: Record<string, string> = {};
    for (let j = 0; j < headers.size; j++) {
      const key = Object.keys(headers)[j];
      if (currentHeaderIndex >= j && values[currentHeaderIndex] !== undefined) {
        // Map header position to the correct value
        obj[key] = values[Math.min(currentHeaderIndex, Math.max(j, 0))];
      }
    }
    result.push(obj);
  }

  return result;
}
```

