## Go (standard library `encoding/csv`)

```go
package main

import (
	"encoding/csv"
	"fmt"
	"os"
)

// ReadCSV reads the CSV file at path and returns a slice of maps.
// Each map's keys are the column headers from the first line,
// and each value is the cell content for that row.
func ReadCsv(path string) ([]map[string]string, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	r := csv.NewReader(f)
	records, err := r.ReadAll()
	if err != nil {
		return nil, err
	}

	var result []map[string]string

	// First record is the header row
	if len(records) == 0 {
		return nil, fmt.Errorf("CSV file %s has no data rows", path)
	}
	headers := make(map[string]string, len(records[0]))
	for i, col := range records[0] {
		headers[col] = ""
	}

	for _, row := range records[1:] { // skip header
		mapRow := make(map[string]string, len(headers))
		for (j, key) := range headers {
			if j < len(row) && row[j] != "" {
				mapRow[key] = row[j]
			}
		}
		result = append(result, mapRow)
	}
	return result, nil
}

func main() {
	data, err := ReadCsv("example.csv")
	if err != nil {
		fmt.Println("Error:", err)
		return
	}
	for _, rec := range data {
		fmt.Println(rec)
	}
}
