import * as fs from 'fs';
import { Writable } from 'stream';

interface TailingState {
  filePath: string;
  lastLine: string | null = null;
}

function tailLogFile(filePath: string): void {
  const state: TailingState = { filePath };

  // Ensure the file exists
  if (!fs.existsSync(state.filePath)) {
    console.log(`Creating log file ${state.filePath}...`);
    fs.writeFileSync(state.filePath, '');
  }

  return new Promise<void>((resolve) => {
    const readStream = fs.createReadStream(
      state.filePath,
      { encoding: 'utf8', errors: 'ignore' }
    );

    let pendingLines: string[] = [];

    // Initial write of existing content
    if (fs.existsSync(state.filePath)) {
      readStream.writeFileSync();
    }

    const onData = (chunk: Buffer) => {
      const line = chunk.toString().split('\n').pop() ?? '';
      pendingLines.push(line);
      
      // Emit new lines that differ from the last one
      for (const l of pendingLines) {
        if (!state.lastLine || l !== state.lastLine) {
          console.log(l.trim());
        }
      }
    };

    readStream.on('data', onData);

    const onEnd = () => resolve();
    
    // Keep tailing: poll every 0.2s
    setInterval(() => {
      if (readStream.getRemaining()) {
        onData(readStream.readFileSync());
      } else {
        // File closed or no more data — wait a bit and retry
        readStream.resume();
      }
    }, 200);
    
    // Handle file close event
    const onClose = () => resolve();
    readStream.on('close', onClose);

    state.lastLine = '';
  });
}

// Usage example:
// tailLogFile('/var/log/syslog');
