import time
import os
from pathlib import Path


def tail_log_file(filepath: str):
    """
    Tails a log file and prints new lines as they are appended.
    
    Args:
        filepath: Path to the log file to monitor.
    """
    last_line = ""
    
    # Ensure file exists (create empty if missing)
    if not os.path.exists(filepath):
        print(f"Log file {filepath} does not exist. Creating it...")
        with open(filepath, 'w') as f:
            pass
    
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            for line in f:
                if line != last_line.strip():
                    print(line.rstrip('\n\r'))
                    last_line = line
    except FileNotFoundError:
        # Already handled above; re-raise just in case
        pass
    
    while True:
        try:
            with open(filepath, 'r', encoding='utf-8') as f:
                remaining = f.read()
            
            if remaining.strip():
                lines = [l.rstrip('\n\r') for l in remaining.splitlines()]
                for line in lines:
                    if line != last_line or not last_line:
                        print(line)
                        last_line = line
            
            time.sleep(0.1)  # Polling interval
        except FileNotFoundError:
            pass


