## 3. Go

```go
package main

import (
	"bufio"
	"fmt"
	"os"
	"path/filepath"
	"time"
)

// TailingState holds the current last line for comparison.
type TailingState struct {
 filePath string
 lastLine  string
}

func tailLogFile(path string) {
	const reader = bufio.NewReaderSize(nil, -1)
	
	// Open file (creates if missing)
	f, err := os.Open(filepath.Join(".", path))
	if err != nil {
		fmt.Printf("Error opening %s: %v\n", path, err)
		return
	}
	defer f.Close()

	tailingState := TailingState{filePath: path}

	for reader.Scan() {
		line := reader.Text()
		if line != tailingState.lastLine {
			fmt.Println(line)
			tailingState.lastLine = line
		}
	}

	// Keep polling in a goroutine
	done := make(chan struct{})
	go func() {
		for reader.Scan() {
			line := reader.Text()
			if line != tailingState.lastLine {
				fmt.Println(line)
				tailingState.lastLine = line
			}
		}
	}()

	select {
	case <-done:
	case <-time.After(5 * time.Second):
		fmt.Println("Tail timed out; keep running.")
	}
}

// Usage example:
// tailLogFile("/var/log/syslog")
