#!/bin/bash

# tails_log_file() - Tails a log file and prints new lines as they are appended.
#
# Args:
#   $1 - Path to the log file (e.g., /var/log/app.log)
#
# Usage:
#   tails_log_file "/path/to/your/logfile"
tail_log_file() {
  local file="$1"

  # Run tail in background
  tail -f "$file" &
}
